    /**
     * Method to retrieve the Feature via an FeaturePrimaryKey.
     * @param 	id Long
     * @return 	Feature
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Feature handle( FindFeatureQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getFeatureId() );
    }
    
    /**
     * Method to retrieve a collection of all Features
     *
     * @param	query	FindAllFeatureQuery 
     * @return 	List<Feature> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Feature> handle( FindAllFeatureQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindFeature,
 * but only if the id matches
 *
 * @param		entity	Feature
 */
	protected void emitFindFeature( Feature entity ) {
		LOGGER.info("handling emitFindFeature" );
		
	    queryUpdateEmitter.emit(FindFeatureQuery.class,
	                            query -> query.getFilter().getFeatureId().equals(entity.getFeatureId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllFeature
	 * 
	 * @param		entity	Feature
	 */
	protected void emitFindAllFeature( Feature entity ) {
		LOGGER.info("handling emitFindAllFeature" );
		
	    queryUpdateEmitter.emit(FindAllFeatureQuery.class,
	                            query -> true,
	                            entity);
	}

